export default function priceFormat({
  amount,
  currency,
  maximumFractionDigits = 0,
}: {
  amount: any;
  currency: any;
  maximumFractionDigits?: number;
}) {
  let usd = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: maximumFractionDigits,
  });

  let eur = Intl.NumberFormat("en-DE", {
    style: "currency",
    currency: "EUR",
    maximumFractionDigits: maximumFractionDigits,
  });

  let turkishlira = Intl.NumberFormat("tr-TR", {
    style: "currency",
    currency: "TRY",
    maximumFractionDigits: maximumFractionDigits,
  });

  if (currency == "TRY") return turkishlira.format(amount);
  else if (currency == "USD") return usd.format(amount);
  else if (currency == "EUR") return eur.format(amount);
}
